package com.example.uniroom;
import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.uniroom.model.Models.*;import com.example.uniroom.network.*;import retrofit2.*;
public class FindRoomActivity extends AppCompatActivity{EditText q;LinearLayout list;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_find_room);q=findViewById(R.id.search);list=findViewById(R.id.list);findViewById(R.id.searchBtn).setOnClickListener(v->load());load();}void load(){list.removeAllViews();Client.api().rooms(q.getText().toString().trim()).enqueue(new Callback<ListResponse<Room>>(){public void onResponse(Call<ListResponse<Room>> c,Response<ListResponse<Room>> r){if(r.body()!=null&&r.body().data!=null)for(Room x:r.body().data){TextView v=new TextView(FindRoomActivity.this);v.setText(x.room_name+"\n"+x.building+" • Floor "+x.floor+" • Capacity "+x.capacity+"\nStatus: "+x.status);v.setTextSize(17);v.setPadding(18,18,18,18);list.addView(v);}}public void onFailure(Call<ListResponse<Room>> c,Throwable t){Toast.makeText(FindRoomActivity.this,"Unable to load rooms",Toast.LENGTH_LONG).show();}});}}
